// Native 0x1423af010. Source weapon and weapons with the same owning controller get !bPropagateToChildren; others get bPropagateToChildren.
bool bAny = false;
AController* SourceController = Source->GetOwningController();
for (AFortWeapon* Weapon : GetAllWeaponActors(Source->GetWorld()))
{
    const bool bSameOwner = (Weapon == Source) || (SourceController && Weapon->GetOwningController() == SourceController);
    const bool bPropagate = bSameOwner ? !bPropagateToChildren : bPropagateToChildren;
    if (SetSceneComponentHiddenInGameInternal(Weapon, SceneComp, bPropagate, bHidden))
    {
        bAny = true;
    }
}
return bAny;
